const crypto = require('crypto');
const envelope = $json.body || $json;
const headers = $json.headers || {};
const signature = String(headers['x-nlcare-signature'] || '');
const secret = String($env.N8N_WEBHOOK_SIGNING_SECRET || '');
const canonicalize = (value) => Array.isArray(value) ? value.map(canonicalize) : (value && typeof value === 'object' ? Object.keys(value).sort().reduce((out, key) => { out[key] = canonicalize(value[key]); return out; }, {}) : value);
const canonicalBody = JSON.stringify(canonicalize(envelope));
const expected = secret ? crypto.createHmac('sha256', secret).update(canonicalBody).digest('hex') : '';
const signatureOk = signature.length === expected.length && signature.length > 0 && crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
const ageSeconds = Math.abs(Date.now() - Date.parse(envelope.created_at || 0)) / 1000;
const payload = envelope.payload || {};
const blocked = ['patient_name','patient_id','raw_patient_message','full_chat_transcript','medical_record_number','date_of_birth','address','phone','email','raw_prompt','raw_response','raw_trace','private_chain_of_thought'];
const blockedPresent = blocked.filter((key) => Object.prototype.hasOwnProperty.call(payload, key));
const required = ['alert_id','event_type','priority','review_path','delivery_scope','recipient_scope'];
const missing = required.filter((key) => payload[key] === undefined || payload[key] === null || payload[key] === '');
const boundaryOk = envelope.payload_redacted === true && envelope.phi_allowed === false && envelope.clinical_validation === false && envelope.healthcare_production_ready === false;
const recipientOk = payload.recipient_scope === 'synthetic_test_recipient';
const ok = signatureOk && ageSeconds <= 300 && blockedPresent.length === 0 && missing.length === 0 && boundaryOk && recipientOk;
return [{json: {ok, signatureOk, freshnessOk: ageSeconds <= 300, blockedPresent, missing, boundaryOk, recipientOk, alert_id: payload.alert_id || null, review_path: payload.review_path || null}}];
